package com.vandorlabs.neoforge.builders;
import com.vandorlabs.neoforge.transfer.*;import java.util.*;import net.minecraft.core.*;import net.minecraft.nbt.*;import net.minecraft.server.level.ServerLevel;import net.minecraft.world.entity.item.ItemEntity;import net.minecraft.world.item.ItemStack;import net.minecraft.world.level.ChunkPos;import net.neoforged.bus.api.SubscribeEvent;import net.neoforged.fml.common.EventBusSubscriber;
/** Journal-owned drops cannot tick, merge, burn or be picked up before both native saves are durable. */
@EventBusSubscriber(modid="vandorlabs")
public final class NativeBuilderDrops {
 static final String KEY="VandorLabsBuilderEscrow";
 record Drop(UUID id,ItemStack item){Drop{item=item.copy();if(item.isEmpty()||item.getCount()>item.getMaxStackSize())throw new IllegalArgumentException("Builder drop");}public ItemStack item(){return item.copy();}}
 private static final Map<ServerLevel,Map<UUID,State>> CHECKPOINTS=new IdentityHashMap<>();private static final Set<ItemEntity> MARKED=Collections.newSetFromMap(new WeakHashMap<>());
 private static final class State {final boolean rollback;final NativeEntityCheckpoint checkpoint;State(ServerLevel w,NativeCellTransactions.Header h,BlockPos at,List<Drop> drops,boolean rollback){this.rollback=rollback;checkpoint=new NativeEntityCheckpoint(w,List.of(new ChunkPos(at)),()->{if(!NativeCellTransactions.reservedBy(w,h,h.root()))throw new IllegalStateException("Builder drop lease lost");},1,(chunk,record)->validateRecord(w,h,at,drops,rollback,record));}}
 private static State state(ServerLevel w,NativeCellTransactions.Header h,BlockPos at,List<Drop> drops,boolean rollback){var map=CHECKPOINTS.computeIfAbsent(w,k->new HashMap<>());var current=map.get(h.operation());if(current==null||current.rollback!=rollback){current=new State(w,h,at,drops,rollback);map.put(h.operation(),current);}return current;}
 static boolean ready(ServerLevel w,NativeCellTransactions.Header h,BlockPos at,List<Drop> drops,boolean rollback){return drops.isEmpty()||state(w,h,at,drops,rollback).checkpoint.loaded();}
 private static CompoundTag marker(NativeCellTransactions.Header h){var tag=new CompoundTag();tag.putUUID("Operation",h.operation());tag.putUUID("Owner",h.owner());tag.putUUID("Actor",h.actor());tag.putLong("Root",h.root().asLong());return tag;}
 private static void freeze(ItemEntity e){e.setPickUpDelay(32767);e.setNoGravity(true);e.setInvulnerable(true);e.setDeltaMovement(0,0,0);}
 static void install(ServerLevel w,NativeCellTransactions.Header h,BlockPos at,List<Drop> drops){if(drops.isEmpty())return;var s=state(w,h,at,drops,false);for(var drop:drops){var actor=s.checkpoint.actor(drop.id);if(actor!=null){if(!(actor instanceof ItemEntity e)||!matches(e,h,at,drop))throw new IllegalStateException("Builder drop UUID already owned");continue;}var e=new ItemEntity(w,at.getX()+.5,at.getY()+.5,at.getZ()+.5,drop.item());e.setUUID(drop.id);e.getPersistentData().put(KEY,marker(h));MARKED.add(e);freeze(e);if(!w.addFreshEntity(e))throw new IllegalStateException("Builder drop publication refused");}}
 private static boolean matches(ItemEntity e,NativeCellTransactions.Header h,BlockPos at,Drop drop){return !e.isRemoved()&&e.getUUID().equals(drop.id)&&ItemStack.matches(e.getItem(),drop.item)&&e.position().distanceToSqr(at.getX()+.5,at.getY()+.5,at.getZ()+.5)<1e-12&&e.getPersistentData().getCompound(KEY).equals(marker(h));}
 static boolean matches(ServerLevel w,NativeCellTransactions.Header h,BlockPos at,List<Drop> drops,boolean rollback){if(drops.isEmpty())return true;var s=state(w,h,at,drops,rollback);for(var drop:drops){var e=s.checkpoint.actor(drop.id);if(rollback){if(e!=null&&!e.isRemoved())return false;}else if(!(e instanceof ItemEntity item)||!matches(item,h,at,drop))return false;}return true;}
 static void rollback(ServerLevel w,NativeCellTransactions.Header h,BlockPos at,List<Drop> drops){if(drops.isEmpty())return;var s=state(w,h,at,drops,true);for(var drop:drops){var e=s.checkpoint.actor(drop.id);if(e==null||e.isRemoved())continue;if(!(e instanceof ItemEntity item)||!matches(item,h,at,drop))throw new IllegalStateException("Builder rollback drop changed");e.discard();}}
 static boolean checkpoint(ServerLevel w,NativeCellTransactions.Header h,BlockPos at,List<Drop> drops,boolean rollback){return drops.isEmpty()||state(w,h,at,drops,rollback).checkpoint.poll();}
 static void released(ServerLevel w,NativeCellTransactions.Header h){var states=CHECKPOINTS.get(w);if(states!=null){states.remove(h.operation());if(states.isEmpty())CHECKPOINTS.remove(w);}}
 private static void validateRecord(ServerLevel w,NativeCellTransactions.Header h,BlockPos at,List<Drop> drops,boolean rollback,CompoundTag record){var found=new HashMap<UUID,CompoundTag>();var ids=new HashSet<UUID>();for(var d:drops)ids.add(d.id);if(record!=null)for(var raw:record.getList("Entities",Tag.TAG_COMPOUND)){var row=(CompoundTag)raw;if(row.hasUUID("UUID")&&ids.contains(row.getUUID("UUID"))&&found.put(row.getUUID("UUID"),row)!=null)throw new IllegalStateException("Duplicate builder drop saved");}for(var drop:drops){var row=found.get(drop.id);if((row!=null)==rollback)throw new IllegalStateException("Missing/unexpected builder drop saved");if(row==null)continue;var p=row.getList("Pos",Tag.TAG_DOUBLE);if(!row.getString("id").equals("minecraft:item")||!NativeMatterMigration.item(row.getCompound("Item")).equals(drop.item.save(w.registryAccess()))||p.size()!=3||p.getDouble(0)!=at.getX()+.5||p.getDouble(1)!=at.getY()+.5||p.getDouble(2)!=at.getZ()+.5||!row.getCompound("NeoForgeData").getCompound(KEY).equals(marker(h)))throw new IllegalStateException("Builder drop saved record differs");}}
 private static boolean held(ItemEntity item){if(!(item.level() instanceof ServerLevel w)||!MARKED.contains(item))return false;if(!NativeBuilderBindings.enabled()){freeze(item);return true;}var tag=item.getPersistentData().getCompound(KEY);if(!tag.getAllKeys().equals(Set.of("Operation","Owner","Actor","Root"))||!tag.hasUUID("Operation")||!tag.hasUUID("Owner")||!tag.hasUUID("Actor")||!tag.contains("Root",4)||!NativeBuilderTransactions.escrowReleased(w,tag,item.getUUID())){freeze(item);return true;}item.getPersistentData().remove(KEY);MARKED.remove(item);item.setPickUpDelay(10);item.setNoGravity(false);item.setInvulnerable(false);return false;}
 @SubscribeEvent public static void joined(net.neoforged.neoforge.event.entity.EntityJoinLevelEvent e){if(e.getLevel() instanceof ServerLevel&&e.getEntity() instanceof ItemEntity item&&item.getPersistentData().contains(KEY)){MARKED.add(item);freeze(item);}}
 @SubscribeEvent public static void tick(net.neoforged.neoforge.event.tick.EntityTickEvent.Pre e){if(e.getEntity() instanceof ItemEntity item&&held(item))e.setCanceled(true);}
 @SubscribeEvent public static void pickup(net.neoforged.neoforge.event.entity.player.ItemEntityPickupEvent.Pre e){if(held(e.getItemEntity()))e.setCanPickup(net.neoforged.neoforge.common.util.TriState.FALSE);}
 @SubscribeEvent public static void unload(net.neoforged.neoforge.event.level.LevelEvent.Unload e){if(e.getLevel() instanceof ServerLevel w)CHECKPOINTS.remove(w);}
 private NativeBuilderDrops(){}
}
